import{_ as s,o as i,c as t,a0 as n}from"./chunks/framework.BZ80FTt7.js";const c=JSON.parse('{"title":"2026-06-30：用 Typora 学 Markdown","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-06-30-markdown-typora.md","filePath":"blog/2026-06-30-markdown-typora.md"}'),e={name:"blog/2026-06-30-markdown-typora.md"};function l(p,a,h,d,o,k){return i(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="_2026-06-30-用-typora-学-markdown" tabindex="-1">2026-06-30：用 Typora 学 Markdown <a class="header-anchor" href="#_2026-06-30-用-typora-学-markdown" aria-label="Permalink to &quot;2026-06-30：用 Typora 学 Markdown&quot;">​</a></h1><p>今天用桌面上的 <code>Markdown教学文档_Typora.md</code> 系统过了一遍 Markdown。之前知道 <code>.md</code> 文件能写笔记和 README，但今天把常用语法、Typora 操作、图片路径、代码块、表格、公式这些点串起来了。</p><h2 id="今天学到的核心" tabindex="-1">今天学到的核心 <a class="header-anchor" href="#今天学到的核心" aria-label="Permalink to &quot;今天学到的核心&quot;">​</a></h2><p>Markdown 本质上是一种轻量级标记语言，用很少的符号表达文档结构。它不追求像 Word 那样精细排版，更适合写学习笔记、技术文档、博客文章和项目说明。</p><p>今天最重要的收获不是背语法，而是理解了 Markdown 适合放进工程化写作流程里：</p><ul><li>源文件是纯文本，直接打开也能读</li><li>适合放到 Git 仓库里管理修改记录</li><li>Typora 适合入门和写作，VS Code 适合维护项目里的文档</li><li>图片、代码、表格、链接都能和普通文字放在同一份文档里</li></ul><h2 id="常用语法整理" tabindex="-1">常用语法整理 <a class="header-anchor" href="#常用语法整理" aria-label="Permalink to &quot;常用语法整理&quot;">​</a></h2><h3 id="标题" tabindex="-1">标题 <a class="header-anchor" href="#标题" aria-label="Permalink to &quot;标题&quot;">​</a></h3><p>标题用 <code>#</code> 表示，<code>#</code> 越多，标题层级越低。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 一级标题</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 二级标题</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 三级标题</span></span></code></pre></div><p>以后写博客时，一级标题只放文章标题，正文里的章节从二级标题开始。</p><h3 id="段落和换行" tabindex="-1">段落和换行 <a class="header-anchor" href="#段落和换行" aria-label="Permalink to &quot;段落和换行&quot;">​</a></h3><p>Markdown 的段落之间要空一行。只按一次回车，很多时候还是同一个段落。如果需要强制换行，可以在行尾加两个空格，或者用编辑器提供的软换行。</p><h3 id="加粗、斜体和删除线" tabindex="-1">加粗、斜体和删除线 <a class="header-anchor" href="#加粗、斜体和删除线" aria-label="Permalink to &quot;加粗、斜体和删除线&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**加粗**</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*斜体*</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**</span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*加粗并斜体*</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">~~删除线~~</span></span></code></pre></div><p>加粗适合标关键概念，但不能整段乱加，否则重点反而不明显。</p><h3 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h3><p>无序列表：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 标题</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 列表</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表格</span></span></code></pre></div><p>有序列表：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 打开 Typora</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 新建 Markdown 文件</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 保存文档</span></span></code></pre></div><p>任务列表：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] 学习标题</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] 学习列表</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 继续写博客</span></span></code></pre></div><p>任务列表很适合记录每天的学习进度。</p><h3 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; 学习 Markdown 的关键，是多写、多看、多修改。</span></span></code></pre></div><p>引用可以用来记录一句总结、摘录或提醒。</p><h3 id="链接和图片" tabindex="-1">链接和图片 <a class="header-anchor" href="#链接和图片" aria-label="Permalink to &quot;链接和图片&quot;">​</a></h3><p>链接：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Typora 官网</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://typora.io/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>图片：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">图片说明</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">图片路径或图片链接</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>今天特别注意到：本地图片最好放到专门的素材目录里，并且和 Markdown 文件保持稳定的相对路径。否则文件移动之后，图片很容易失效。</p><p>推荐结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文章.md</span></span>
<span class="line"><span>文章.assets/</span></span>
<span class="line"><span>  01.png</span></span>
<span class="line"><span>  02.png</span></span></code></pre></div><h3 id="表格" tabindex="-1">表格 <a class="header-anchor" href="#表格" aria-label="Permalink to &quot;表格&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 工具 | 适合场景 | 特点 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| --- | --- | --- |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Typora | 学习和写笔记 | 所见即所得 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| VS Code | 项目文档 | 适合代码仓库 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Obsidian | 知识库 | 适合长期积累 |</span></span></code></pre></div><p>表格适合横向比较。以后比较工具、方案、学习路线时可以优先用表格。</p><h3 id="代码" tabindex="-1">代码 <a class="header-anchor" href="#代码" aria-label="Permalink to &quot;代码&quot;">​</a></h3><p>行内代码用反引号：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">使用 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`print()\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 输出内容。</span></span></code></pre></div><p>代码块用三个反引号，并且最好标注语言：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`python</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">def hello():</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    print(&quot;Hello, Markdown!&quot;)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span></code></pre></div><p>写技术博客时，代码块一定要标语言，这样预览时更清楚。</p><h3 id="注释和-html-混写" tabindex="-1">注释和 HTML 混写 <a class="header-anchor" href="#注释和-html-混写" aria-label="Permalink to &quot;注释和 HTML 混写&quot;">​</a></h3><p>Markdown 可以混写一部分 HTML。今天记住了几个常见写法：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 这是一条注释，不会在正常预览中显示 --&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;u&gt;下划线文字&lt;/u&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;kbd&gt;Ctrl&lt;/kbd&gt; + &lt;kbd&gt;S&lt;/kbd&gt;</span></span></code></pre></div><p>注释适合给自己留 TODO，但不能写密码、密钥、账号这类敏感信息。</p><h3 id="公式" tabindex="-1">公式 <a class="header-anchor" href="#公式" aria-label="Permalink to &quot;公式&quot;">​</a></h3><p>行内公式：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">勾股定理：$a^2 + b^2 = c^2$。</span></span></code></pre></div><p>块级公式：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$$</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">E = mc^2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$$</span></span></code></pre></div><p>公式适合数学推导类笔记，但不同平台支持程度不一样，发布前要预览。</p><h2 id="typora-和-vs-code-的分工" tabindex="-1">Typora 和 VS Code 的分工 <a class="header-anchor" href="#typora-和-vs-code-的分工" aria-label="Permalink to &quot;Typora 和 VS Code 的分工&quot;">​</a></h2><p>今天把工具选择也想清楚了：</p><table tabindex="0"><thead><tr><th>工具</th><th>我以后怎么用</th></tr></thead><tbody><tr><td>Typora</td><td>写学习笔记、整理语法、导出 PDF</td></tr><tr><td>VS Code</td><td>写项目 README、博客文章、和代码一起维护的文档</td></tr><tr><td>Obsidian</td><td>以后如果要做长期知识库再考虑</td></tr><tr><td>Word/WPS</td><td>正式文档、论文、公文、需要复杂排版时使用</td></tr></tbody></table><p>目前阶段，Typora 负责入门和写作体验，VS Code 负责项目文档和博客维护。</p><h2 id="今天形成的写作习惯" tabindex="-1">今天形成的写作习惯 <a class="header-anchor" href="#今天形成的写作习惯" aria-label="Permalink to &quot;今天形成的写作习惯&quot;">​</a></h2><p>以后写 Markdown 时先按这个顺序来：</p><ol><li>先写文章标题和二级标题，搭好结构。</li><li>再补正文，不要一上来纠结排版。</li><li>并列内容用列表，横向比较用表格。</li><li>代码块标语言，图片放专门素材目录。</li><li>写完后在目标平台预览一次，尤其检查图片、表格、公式和链接。</li></ol><h2 id="今日总结" tabindex="-1">今日总结 <a class="header-anchor" href="#今日总结" aria-label="Permalink to &quot;今日总结&quot;">​</a></h2><p>Markdown 的语法本身不难，真正有用的是它能把学习笔记、项目说明和博客记录统一成一种轻量、清晰、容易维护的格式。</p><p>今天这篇博客也算是一次练习：用 Markdown 记录 Markdown。接下来写 C++、RCS、ROS2 的学习笔记时，就按这个格式继续积累。</p>`,64)])])}const g=s(e,[["render",l]]);export{c as __pageData,g as default};
